<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إعدادات المتجر | لمسة أنوثة</title><link rel="icon" href="{{ asset('images/logo.jpeg') }}"><style>
*{box-sizing:border-box;margin:0;padding:0}:root{--red:#e21b23;--bg:#f4f5f7;--card:#fff;--text:#171717;--muted:#777;--border:#e2e4e7;--shadow:0 8px 28px rgba(0,0,0,.07)}body.dark{--bg:#101010;--card:#191919;--text:#f5f5f5;--muted:#aaa;--border:#303030;--shadow:0 12px 35px rgba(0,0,0,.35)}body{font-family:Arial,"Segoe UI",sans-serif;background:var(--bg);color:var(--text)}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}.app{min-height:100vh;display:grid;grid-template-columns:245px 1fr}.side{background:#090909;color:#eee;padding:18px 13px}.logo{height:98px;display:flex;align-items:center;justify-content:center;border-bottom:1px solid #292929;margin-bottom:15px}.logo img{width:205px;height:86px;object-fit:contain}.nav a{display:flex;gap:10px;padding:12px;border-radius:9px;margin:3px 0;font-size:14px}.nav a:hover,.nav a.active{background:var(--red)}.main{min-width:0}.top{height:74px;padding:0 3%;display:flex;align-items:center;justify-content:space-between;background:var(--card);border-bottom:1px solid var(--border)}.top h1{font-size:21px}.tools{display:flex;gap:8px}.tool{height:40px;padding:0 12px;border:1px solid var(--border);border-radius:8px;background:var(--card);color:var(--text);cursor:pointer}.content{padding:24px 3% 55px}.headline{margin-bottom:17px}.headline p{color:var(--muted);font-size:13px;margin-top:5px}.layout{display:grid;grid-template-columns:220px 1fr;gap:16px}.settings-nav{background:var(--card);border:1px solid var(--border);border-radius:13px;padding:9px;height:max-content;position:sticky;top:95px}.settings-nav button{width:100%;display:flex;gap:9px;align-items:center;padding:11px;border:0;border-radius:8px;background:transparent;color:var(--text);cursor:pointer;text-align:start;margin:2px 0}.settings-nav button:hover,.settings-nav button.active{background:var(--red);color:#fff}.page{display:none}.page.active{display:block}.card{background:var(--card);border:1px solid var(--border);border-radius:13px;box-shadow:var(--shadow);margin-bottom:15px}.card-head{padding:17px 19px;border-bottom:1px solid var(--border)}.card-head h2{font-size:18px}.card-head p{font-size:12px;color:var(--muted);margin-top:5px}.card-body{padding:19px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field.full{grid-column:1/-1}.field label{display:block;font-size:12px;margin-bottom:7px}.field input,.field select,.field textarea{width:100%;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--text);padding:0 11px;outline:0}.field input,.field select{height:44px}.field textarea{height:90px;padding-top:11px}.logo-upload{display:flex;align-items:center;gap:17px}.logo-preview{width:210px;height:100px;border:1px dashed var(--border);border-radius:10px;display:grid;place-items:center;background:#090909}.logo-preview img{width:190px;height:85px;object-fit:contain}.primary,.outline{height:42px;padding:0 15px;border-radius:8px;cursor:pointer}.primary{border:0;background:var(--red);color:#fff}.outline{border:1px solid var(--border);background:var(--card);color:var(--text)}.save-row{display:flex;align-items:center;gap:11px;justify-content:flex-end;padding-top:15px;border-top:1px solid var(--border);margin-top:18px}.notice{display:none;color:#087443;background:#d1fae5;padding:9px 12px;border-radius:8px;font-size:12px}.option{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 0;border-bottom:1px solid var(--border)}.option:last-child{border:0}.option h3{font-size:14px}.option p{font-size:12px;color:var(--muted);margin-top:4px;line-height:1.5}.switch{position:relative;width:48px;height:27px;flex:none}.switch input{display:none}.slider{position:absolute;inset:0;background:#bbb;border-radius:30px;cursor:pointer}.slider:after{content:"";position:absolute;width:21px;height:21px;top:3px;left:3px;border-radius:50%;background:#fff;transition:.2s}.switch input:checked+.slider{background:var(--red)}.switch input:checked+.slider:after{transform:translateX(21px)}[dir=rtl] .switch input:checked+.slider:after{transform:translateX(-21px)}[dir=rtl] .slider:after{left:auto;right:3px}.method{display:grid;grid-template-columns:55px 1fr auto;align-items:center;gap:13px;padding:15px;border:1px solid var(--border);border-radius:10px;margin-bottom:10px}.method-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:12px;background:var(--bg);font-size:23px}.method p{font-size:12px;color:var(--muted);margin-top:4px}.currency-table{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:start;padding:13px;border-bottom:1px solid var(--border);font-size:12px}th{background:var(--bg);color:var(--muted);font-weight:normal}.flag{width:28px;height:19px;object-fit:cover;border-radius:3px;vertical-align:middle;margin-inline-end:7px}.staff{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:14px 0;border-bottom:1px solid var(--border)}.staff-info{display:flex;align-items:center;gap:10px}.avatar{width:39px;height:39px;display:grid;place-items:center;border-radius:50%;background:rgba(226,27,35,.12);color:var(--red)}.staff small{display:block;color:var(--muted);margin-top:4px}.danger{border:1px solid #fecaca;background:#fff1f2;color:#b91c1c;border-radius:10px;padding:16px;margin-top:12px}.danger h3{margin-bottom:6px}.danger p{font-size:12px;line-height:1.6}.danger button{margin-top:11px;border:0;background:#b91c1c;color:#fff;padding:9px 13px;border-radius:7px}.integration{display:grid;grid-template-columns:repeat(2,1fr);gap:11px}.integration .method{margin:0}.status{padding:5px 8px;border-radius:20px;background:#eee;color:#777;font-size:10px}
@media(max-width:950px){.layout{grid-template-columns:1fr}.settings-nav{position:static;display:flex;overflow:auto}.settings-nav button{white-space:nowrap;width:auto}}@media(max-width:800px){.app{grid-template-columns:1fr}.side{display:none}}@media(max-width:560px){.form-grid,.integration{grid-template-columns:1fr}.field.full{grid-column:auto}.logo-upload,.method{grid-template-columns:1fr;display:grid}.save-row{flex-direction:column}.save-row>*{width:100%}.top h1{font-size:17px}}
</style></head><body><div class="app"><aside class="side"><a class="logo" href="{{ url('/admin') }}"><img src="{{ asset('images/logo.jpeg') }}" alt="لمسة أنوثة"></a><nav class="nav"><a href="{{ url('/admin') }}">⌂ <span data-t="dashboard">لوحة التحكم</span></a><a href="{{ url('/admin/orders') }}">▤ <span data-t="orders">الطلبات</span></a><a href="{{ url('/admin/finance') }}">▥ <span data-t="finance">المالية</span></a><a href="{{ url('/admin/marketing') }}">★ <span data-t="marketing">التسويق</span></a><a class="active" href="{{ url('/admin/settings') }}">⚙ <span data-t="settings">الإعدادات</span></a></nav></aside><main class="main"><header class="top"><h1 data-t="settings">إعدادات المتجر</h1><div class="tools"><button class="tool" id="theme">☾</button><button class="tool" id="language">English</button></div></header><div class="content"><section class="headline"><h2 data-t="settingsCenter">مركز الإعدادات</h2><p data-t="intro">تحكم في بيانات المتجر والدفع والشحن والتكاملات والأمان.</p></section><div class="layout"><nav class="settings-nav"><button class="active" data-page="general">🏪 <span data-t="general">عام</span></button><button data-page="localization">🌐 <span data-t="localization">اللغة والعملات</span></button><button data-page="payments">💳 <span data-t="payments">الدفع</span></button><button data-page="shipping">🚚 <span data-t="shipping">الشحن</span></button><button data-page="tax">% <span data-t="tax">الضرائب والفواتير</span></button><button data-page="integrations">🔗 <span data-t="integrations">التكاملات</span></button><button data-page="notifications">🔔 <span data-t="notifications">الإشعارات</span></button><button data-page="staff">👥 <span data-t="staff">الموظفون والصلاحيات</span></button><button data-page="security">🔒 <span data-t="security">الأمان والنسخ</span></button></nav><div>
<section class="page active" id="general"><form class="card setting-form"><div class="card-head"><h2 data-t="storeInfo">بيانات المتجر</h2><p data-t="storeInfoText">الاسم والشعار ومعلومات التواصل.</p></div><div class="card-body"><div class="logo-upload"><div class="logo-preview"><img src="{{ asset('images/logo.jpeg') }}" alt="logo"></div><div><button type="button" class="outline" data-t="changeLogo">تغيير الشعار</button><p style="color:var(--muted);font-size:11px;margin-top:7px" data-t="logoHint">PNG أو JPEG بخلفية شفافة أو داكنة.</p></div></div><br><div class="form-grid"><div class="field"><label data-t="nameAr">اسم المتجر بالعربية</label><input value="لمسة أنوثة"></div><div class="field"><label data-t="nameEn">اسم المتجر بالإنجليزية</label><input value="Lamset Anotha"></div><div class="field"><label data-t="phone">رقم الهاتف</label><input value="95426555"></div><div class="field"><label>Instagram</label><input value="@mkm13390"></div><div class="field full"><label data-t="address">العنوان</label><input></div><div class="field full"><label data-t="description">وصف المتجر</label><textarea></textarea></div></div><div class="save-row"><span class="notice"></span><button class="primary" data-t="save">حفظ التغييرات</button></div></div></form></section>
<section class="page" id="localization"><div class="card"><div class="card-head"><h2 data-t="languageCurrency">اللغة والعملات</h2></div><div class="card-body"><div class="form-grid"><div class="field"><label data-t="defaultLanguage">اللغة الافتراضية</label><select><option>العربية</option><option>English</option></select></div><div class="field"><label data-t="defaultCurrency">العملة الافتراضية</label><select><option>OMR — ر.ع</option></select></div></div><br><div class="currency-table"><table><thead><tr><th data-t="currency">العملة</th><th data-t="rate">سعر التحويل</th><th data-t="enabled">مفعلة</th></tr></thead><tbody><tr><td><img class="flag" src="https://flagcdn.com/w40/om.png">OMR</td><td>1.000</td><td>✓</td></tr><tr><td><img class="flag" src="https://flagcdn.com/w40/ae.png">AED</td><td><input value="9.55" style="width:85px"></td><td><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></td></tr><tr><td><img class="flag" src="https://flagcdn.com/w40/sa.png">SAR</td><td><input value="9.75" style="width:85px"></td><td><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></td></tr><tr><td><img class="flag" src="https://flagcdn.com/w40/kw.png">KWD</td><td><input value="0.80" style="width:85px"></td><td><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></td></tr></tbody></table></div><div class="save-row"><span class="notice"></span><button class="primary" data-t="save">حفظ</button></div></div></div></section>
<section class="page" id="payments"><div class="card"><div class="card-head"><h2 data-t="paymentMethods">طرق الدفع</h2><p data-t="paymentText">فعّل الطرق المتاحة واضبط بياناتها.</p></div><div class="card-body"><div class="method"><span class="method-icon">💵</span><div><h3 data-t="cod">الدفع عند الاستلام</h3><p data-t="codText">تحصيل المبلغ عند توصيل الطلب.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="method"><span class="method-icon">📱</span><div><h3 data-t="transfer">التحويل البنكي</h3><p data-t="transferText">أضف رقم الحساب واسم البنك وتعليمات التحويل.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="method"><span class="method-icon">🏦</span><div><h3>Bank Muscat Gateway</h3><p data-t="credentials">يحتاج مفاتيح وربط بوابة الدفع.</p></div><span class="status" data-t="notConnected">غير مربوط</span></div><div class="method"><span class="method-icon"></span><div><h3>Apple Pay</h3><p data-t="credentials">يحتاج مفاتيح وربط بوابة الدفع.</p></div><span class="status" data-t="notConnected">غير مربوط</span></div><div class="save-row"><span class="notice"></span><button class="primary" data-t="save">حفظ</button></div></div></div></section>
<section class="page" id="shipping"><div class="card"><div class="card-head"><h2 data-t="shippingSettings">إعدادات الشحن</h2></div><div class="card-body"><div class="option"><div><h3 data-t="deliveryOman">التوصيل داخل عُمان</h3><p data-t="deliveryOmanText">تحديد سعر مختلف لكل محافظة أو ولاية.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="form-grid" style="margin-top:15px"><div class="field"><label data-t="muscatFee">رسوم مسقط</label><input type="number" step="0.001" value="0"></div><div class="field"><label data-t="otherFee">بقية المحافظات</label><input type="number" step="0.001" value="0"></div><div class="field"><label data-t="freeAbove">شحن مجاني للطلبات فوق</label><input type="number" step="0.001"></div><div class="field"><label data-t="deliveryDays">مدة التوصيل</label><input value="2-5"></div></div><div class="option"><div><h3 data-t="pickup">الاستلام من المتجر</h3><p data-t="pickupText">خيار مجاني عند إتمام الطلب.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="save-row"><span class="notice"></span><button class="primary" data-t="save">حفظ</button></div></div></div></section>
<section class="page" id="tax"><div class="card"><div class="card-head"><h2 data-t="taxInvoices">الضرائب والفواتير</h2></div><div class="card-body"><div class="option"><div><h3 data-t="vat">ضريبة القيمة المضافة</h3><p data-t="vatText">تفعيل الضريبة وتحديد الرقم والنسبة.</p></div><label class="switch"><input type="checkbox"><span class="slider"></span></label></div><div class="form-grid" style="margin-top:15px"><div class="field"><label data-t="taxNumber">الرقم الضريبي</label><input></div><div class="field"><label data-t="taxRate">نسبة الضريبة</label><input type="number" value="5"></div><div class="field"><label data-t="invoicePrefix">بادئة رقم الفاتورة</label><input value="INV-"></div><div class="field"><label data-t="nextInvoice">رقم الفاتورة التالي</label><input value="1001"></div></div><div class="save-row"><span class="notice"></span><button class="primary" data-t="save">حفظ</button></div></div></div></section>
<section class="page" id="integrations"><div class="card"><div class="card-head"><h2 data-t="externalServices">الخدمات الخارجية</h2></div><div class="card-body integration"><div class="method"><span class="method-icon">G</span><div><h3>Google Login</h3><p data-t="socialLogin">تسجيل الدخول الاجتماعي</p></div><span class="status" data-t="notConnected">غير مربوط</span></div><div class="method"><span class="method-icon"></span><div><h3>Apple Login</h3><p data-t="socialLogin">تسجيل الدخول الاجتماعي</p></div><span class="status" data-t="notConnected">غير مربوط</span></div><div class="method"><span class="method-icon">☏</span><div><h3>WhatsApp API</h3><p data-t="ordersMessages">رسائل الطلبات والتسويق</p></div><span class="status" data-t="notConnected">غير مربوط</span></div><div class="method"><span class="method-icon">✉</span><div><h3>Email / SMTP</h3><p data-t="emails">الفواتير والتنبيهات</p></div><span class="status" data-t="notConnected">غير مربوط</span></div></div></div></section>
<section class="page" id="notifications"><div class="card"><div class="card-head"><h2 data-t="notificationSettings">إعدادات الإشعارات</h2></div><div class="card-body"><div class="option"><div><h3 data-t="newOrderNotif">طلب جديد للإدارة</h3><p data-t="newOrderNotifText">إشعار عند وصول أي طلب جديد.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="option"><div><h3 data-t="statusNotif">تحديث حالة الطلب للعميلة</h3><p>WhatsApp / Email</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="option"><div><h3 data-t="stockNotif">تنبيه انخفاض المخزون</h3><p data-t="stockNotifText">إشعار عند بلوغ الحد الأدنى.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="save-row"><span class="notice"></span><button class="primary" data-t="save">حفظ</button></div></div></div></section>
<section class="page" id="staff"><div class="card"><div class="card-head"><h2 data-t="staffRoles">الموظفون والصلاحيات</h2></div><div class="card-body"><div class="staff"><div class="staff-info"><span class="avatar">A</span><div><b>Administrator</b><small data-t="fullAccess">صلاحية كاملة</small></div></div><button class="outline" data-t="edit">تعديل</button></div><button class="primary" style="margin-top:15px" data-t="addStaff">+ إضافة موظف</button><div class="option" style="margin-top:15px"><div><h3 data-t="roles">الأدوار</h3><p data-t="rolesText">مدير، كاشير، مخزون، محاسب، تسويق وخدمة عملاء.</p></div></div></div></div></section>
<section class="page" id="security"><div class="card"><div class="card-head"><h2 data-t="securityBackup">الأمان والنسخ الاحتياطي</h2></div><div class="card-body"><div class="option"><div><h3 data-t="twoFactor">التحقق بخطوتين</h3><p data-t="twoFactorText">حماية حسابات الإدارة برمز إضافي.</p></div><label class="switch"><input type="checkbox"><span class="slider"></span></label></div><div class="option"><div><h3 data-t="activityLog">سجل النشاط</h3><p data-t="activityText">تسجيل عمليات الدخول والتعديل والحذف.</p></div><label class="switch"><input type="checkbox" checked><span class="slider"></span></label></div><div class="option"><div><h3 data-t="backup">نسخ احتياطي تلقائي</h3><p data-t="backupText">نسخة يومية من قاعدة البيانات والملفات.</p></div><label class="switch"><input type="checkbox"><span class="slider"></span></label></div><button class="outline" style="margin-top:15px" data-t="backupNow">إنشاء نسخة الآن</button><div class="danger"><h3 data-t="maintenance">وضع الصيانة</h3><p data-t="maintenanceText">إيقاف واجهة العملاء مؤقتًا مع بقاء لوحة الإدارة متاحة.</p><button data-t="enableMaintenance">تفعيل وضع الصيانة</button></div></div></div></section>
